scwin.gridView1_onscrollend = function() {
    console.log("onscrollend");
};
scwin.gridView1_onscrollstart = function() {
    console.log("onscrollstart");
    localStorage.setItem("log", "true");
};
scwin.checkVal = function() {
    return localStorage.getItem("log") == "true";
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 1000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 0");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Created By: Sangwook
    //Created By: 2021.01.20
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
